class TestImportTemplateGroup(FrappeTestCase):
	# each test counts folders and prefixes from scratch
	def tearDown(self):
		frappe.db.rollback()

	def import_routes(self):
		result = import_template_group("zz-harbour")
		routes = frappe.get_all("Builder Page", {"name": ["in", result["pages"]]}, pluck="route")
		return result["folder"], sorted(routes)

	def test_imports_into_a_new_folder_under_one_route_prefix(self):
		folder, routes = self.import_routes()
		self.assertEqual(folder, "Zz Harbour")
		self.assertEqual(routes, ["zz-harbour/guides/arrival", "zz-harbour/home", "zz-harbour/rooms"])

	def test_a_repeat_import_takes_the_next_folder_and_prefix(self):
		self.import_routes()
		folder, routes = self.import_routes()
		self.assertEqual(folder, "Zz Harbour 2")
		self.assertTrue(all(route.startswith("zz-harbour-2/") for route in routes))

	def test_a_taken_folder_name_is_skipped_and_the_transaction_survives(self):
		frappe.get_doc({"doctype": "Builder Project Folder", "folder_name": "Zz Harbour"}).insert()
		self.assertFalse(insert_folder("Zz Harbour"))
		self.assertEqual(create_import_folder("Zz Harbour", "zz-harbour"), ("Zz Harbour 2", "zz-harbour-2"))

	def test_a_group_with_no_fetchable_pages_creates_no_folder(self):
		with patch("builder.api.hub_get", lambda method, page=None: None):
			self.assertRaises(frappe.ValidationError, import_template_group, "zz-harbour")
		self.assertFalse(frappe.db.exists("Builder Project Folder", "Zz Harbour"))

from frappe.tests.utils import FrappeTestCase

from builder.ai.agent.loop import (
	SYSTEM_CACHE_CONTROL,
	TURN_CACHE_CONTROL,
	AgentRunner,
	marker_position,
)


def msg(role="user", content="x", **extra):
	return {"role": role, "content": content, **extra}


def tool_call_msg():
	return {"role": "assistant", "content": None, "tool_calls": [{"id": "t1"}]}


class TestCacheMarkers(FrappeTestCase):
	def refresh(self, messages, history_end, prompt):
		runner = AgentRunner("hi", model="m", api_key="k")
		runner.history_end_index = history_end
		runner.prompt_index = prompt
		runner.refresh_cache_markers(messages)

	def test_cross_turn_breakpoints_get_the_long_ttl(self):
		messages = [msg("system"), msg(), msg("assistant"), msg(), msg("assistant"), msg()]

		self.refresh(messages, history_end=2, prompt=3)

		# System and end-of-history survive the between-turn gap; the rest are per-round.
		self.assertEqual(messages[0]["cache_control"], SYSTEM_CACHE_CONTROL)
		self.assertEqual(messages[2]["cache_control"], SYSTEM_CACHE_CONTROL)
		self.assertEqual(messages[3]["cache_control"], TURN_CACHE_CONTROL)
		self.assertEqual(messages[5]["cache_control"], TURN_CACHE_CONTROL)

	def test_marker_never_lands_on_a_content_less_message(self):
		messages = [msg("system"), msg(), tool_call_msg()]

		self.refresh(messages, history_end=0, prompt=1)

		self.assertNotIn("cache_control", messages[2])
		self.assertIn("cache_control", messages[1])

	def test_marker_position_walks_back_to_content(self):
		messages = [msg(), msg("tool", "result"), tool_call_msg()]

		self.assertEqual(marker_position(messages, 2), 1)
		self.assertEqual(marker_position(messages, 1), 1)

// Placed in separate file to setup frappe resource fetcher before loading the app.
import { frappeRequest, setConfig } from "frappe-ui";
import { editorDemo } from "@/utils/editorDemo";
import { createEditorDemoBackend } from "@/utils/editorDemoBackend";

setConfig("resourceFetcher", editorDemo ? createEditorDemoBackend(editorDemo) : frappeRequest);

import builderProjectFolder from "@/data/builderProjectFolder";
import router from "@/router";
import useBuilderStore from "@/stores/builderStore";
import usePageStore from "@/stores/pageStore";
import { __ } from "@/translation";
import { BuilderPage, BuilderProjectFolder } from "@/types/doctypes";
import { webPages } from "@/data/webPage";
import { createListResource, createResource, dialog } from "frappe-ui";
import { ref } from "vue";

export const FOLDER_PAGE_LIMIT = 500;

// the pages of one folder, the one the open page lives in; PagesSection points it at that folder
export const folderPages = createListResource({
	method: "GET",
	doctype: "Builder Page",
	fields: ["name", "page_name", "page_title", "route", "project_folder", "published", "staging", "is_standard"],
	filters: { is_template: 0, project_folder: "" },
	// creation order keeps a template's pages in the order the template lists them
	orderBy: "creation asc",
	pageLength: FOLDER_PAGE_LIMIT,
});

// bumped after any page change so every page list refreshes from the server
export const pagesVersion = ref(0);

export function notifyPagesChanged() {
	pagesVersion.value++;
	webPages.reload();
}

const isOpen = (page: BuilderPage) => page.name === usePageStore().activePage?.name;

export async function openPage(page: BuilderPage) {
	if (isOpen(page)) return;
	const pageStore = usePageStore();
	// a page switch mid-debounce would save the old edits onto whichever page is loaded by then
	if (pageStore.savingPage) await pageStore.waitTillPageIsSaved();
	router.push({ name: "builder", params: { pageId: page.name } });
}

// template titles repeat the site name ("Rooms · Tide House"), the folder already says it
export const shortTitle = (page: BuilderPage) =>
	(page.page_title || page.page_name || "").split(/\s+[·|—]\s+/)[0];

export function createPageIn(folder: string) {
	router.push({ name: "builder", params: { pageId: "new" }, query: folder ? { folder } : {} });
}

// the open page saves through the page store so its unsaved state stays consistent
async function setPageValue(page: BuilderPage, field: keyof BuilderPage, value: string) {
	if (isOpen(page)) {
		// the list refreshes below, so wait for the save or it comes back with the old value
		await usePageStore().updateActivePage(field, value);
	} else {
		await createResource({ url: "frappe.client.set_value" }).submit({
			doctype: "Builder Page",
			name: page.name,
			fieldname: field,
			value,
		});
	}
	notifyPagesChanged();
}

const movePage = (page: BuilderPage, folder: string) => {
	if ((page.project_folder || "") !== folder) setPageValue(page, "project_folder", folder);
};

function renamePage(page: BuilderPage) {
	dialog.prompt({
		title: __("Rename Page"),
		size: "sm",
		confirmLabel: __("Rename"),
		fields: [{ name: "title", label: __("Title"), required: true, defaultValue: page.page_title || "" }],
		onConfirm: ({ values }) => setPageValue(page, "page_title", values.title),
	});
}

function firstPageIn(folder: string, extraFilters = {}): Promise<BuilderPage[]> {
	return createResource({ url: "frappe.client.get_list" }).submit({
		doctype: "Builder Page",
		fields: ["name"],
		filters: { is_template: 0, project_folder: folder, ...extraFilters },
		order_by: "creation asc",
		limit_page_length: 1,
	});
}

// the page after it in its folder's loaded list, else the one before
function loadedNeighbour(page: BuilderPage) {
	const siblings = (folderPages.data ?? []).filter((row: BuilderPage) => row.project_folder === page.project_folder);
	const index = siblings.findIndex((row: BuilderPage) => row.name === page.name);
	if (index === -1) return;
	return siblings[index + 1] ?? siblings[index - 1];
}

export async function deletePage(page: BuilderPage) {
	const wasOpen = isOpen(page);
	const neighbour = wasOpen ? loadedNeighbour(page) : undefined;
	if (!(await usePageStore().deletePage(page))) return;
	notifyPagesChanged();
	if (!wasOpen) return;
	// a search or the row limit can leave the loaded list without the folder's other pages
	const next = neighbour ?? (page.project_folder ? (await firstPageIn(page.project_folder))[0] : undefined);
	router.push(next ? { name: "builder", params: { pageId: next.name } } : { name: "home" });
}

// protected pages and a read-only editor must not be renamed, moved or deleted from here
function isLocked(page: BuilderPage) {
	return (Boolean(page.is_standard) && !window.is_developer_mode) || (isOpen(page) && useBuilderStore().readOnlyMode);
}

